import "./Header.css";
import { Link } from "react-router-dom";

function Header() {
  return (
    <header className="header">
      <Link className="logo" to="/">
        Prime Flix
      </Link>
       <Link className="favoritos" to="/Favoritos">
        Meus Filmes
      </Link>
    </header>
  );
}

export default Header;
